//! The experimental `path` global (core's `codemode/path.ts`, upstream 2.3.1 #64476): programs run through upstream
//! 2.3.1's Code Mode with core's `path` extension (`tests/fixtures/path/path-2.3.1.json`, regenerated by
//! `tests/recorder/path-cases.ts`), on a POSIX host in /work/proj and as a Windows host would run them in
//! C:\work\proj, with the server's working directory at /usr (which `win32.resolve("D:x")` and
//! `win32.toNamespacedPath("x")` read). Both run on every platform.

mod common;

use std::sync::Arc;

use oc_codemode::codemode::{CodeMode, ExecutionLimits};
use oc_codemode::host::NoTools;
use oc_codemode::path::{extension_in, Flavour};
use serde_json::Value as Json;

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn path_programs_match_upstream() {
    let file = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/path/path-2.3.1.json");
    let cases: Vec<Json> = serde_json::from_str(&std::fs::read_to_string(file).unwrap()).unwrap();
    let mut failures = Vec::new();
    for case in &cases {
        let (host, directory) = match case["host"].as_str() {
            Some("win32") => (Flavour::Win32, "C:\\work\\proj"),
            _ => (Flavour::Posix, "/work/proj"),
        };
        let runtime =
            CodeMode::new(Vec::new(), Arc::new(NoTools), vec![extension_in(host, directory, "/usr")], ExecutionLimits::default()).unwrap();
        let code = case["code"].as_str().unwrap();
        let ours = runtime.execute(code).await.to_json();
        if !common::json_eq(&ours, &case["result"]) {
            failures.push(format!("[{}] {code}\n  expected {}\n  got      {ours}", case["host"], case["result"]));
        }
    }
    assert!(failures.is_empty(), "{} of {} differ:\n{}", failures.len(), cases.len(), failures.join("\n\n"));
}

// Upstream core's `tool-execute.test.ts` "path", with the host's own flavour.
fn session() -> (CodeMode, bool) {
    let windows = cfg!(windows);
    let directory = if windows { "C:\\session\\dir" } else { "/session/dir" };
    let runtime =
        CodeMode::new(Vec::new(), Arc::new(NoTools), vec![oc_codemode::path::extension(directory)], ExecutionLimits::default()).unwrap();
    (runtime, windows)
}

async fn run(runtime: &CodeMode, code: &str) -> Json {
    match runtime.execute(code).await {
        oc_codemode::codemode::ExecResult::Success { value, .. } => value,
        failed => panic!("{code}: {}", failed.to_json()),
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn path_is_the_host_s_path_module_resolving_against_the_session_s_directory() {
    let (runtime, windows) = session();
    let got = run(
        &runtime,
        r#"return [path.resolve("a", "b"), path.relative("a", "c"), path.join("out", "..", "x.txt"), path.basename("/a/b.ts", ".ts"), path.posix.join("a", "b"), path.win32.join("a", "b"), path.sep]"#,
    )
    .await;
    let expected = if windows {
        serde_json::json!(["C:\\session\\dir\\a\\b", "..\\c", "x.txt", "b", "a/b", "a\\b", "\\"])
    } else {
        serde_json::json!(["/session/dir/a/b", "../c", "x.txt", "b", "a/b", "a\\b", "/"])
    };
    assert_eq!(got, expected);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_other_platform_s_flavour_resolves_from_its_own_root_not_the_server_s_working_directory() {
    let (runtime, windows) = session();
    let other = if windows { "posix" } else { "win32" };
    let got = run(&runtime, &format!("return [path.{other}.resolve(\"a\")]")).await;
    assert_eq!(got, serde_json::json!([if windows { "/a" } else { "\\a" }]));
    let cwd = std::env::current_dir().unwrap().to_string_lossy().into_owned();
    assert!(!got[0].as_str().unwrap().contains(&cwd));
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn path_is_importable_by_its_node_module_names() {
    let (runtime, windows) = session();
    let got = run(
        &runtime,
        r#"import { join } from "node:path"
           const posix = require("path").posix
           return [join("a", "b"), posix.dirname("a/b")]"#,
    )
    .await;
    assert_eq!(got, serde_json::json!([if windows { "a\\b" } else { "a/b" }, "a"]));
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn without_the_extension_there_is_no_path() {
    let runtime = CodeMode::new(Vec::new(), Arc::new(NoTools), Vec::new(), ExecutionLimits::default()).unwrap();
    assert_eq!(run(&runtime, "return [typeof path]").await, serde_json::json!(["undefined"]));
    // A runtime made with it can leave it out of a run (core gives `path` only with `full_codemode`).
    let (with, _) = session();
    assert_eq!(run(&with.select_extensions(&[]).unwrap(), "return [typeof path]").await, serde_json::json!(["undefined"]));
}
